head.script:
scwin.screenId = "jldinf35101";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "td_20", attr: "__html", fn: function () { return ([String(dma_map.get("stdCd")), String(dma_map.get("srtCd"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(dma_map.get("stdCd")) + " <strong class=\"\"> (" + String(dma_map.get("srtCd")) + ")</strong>") : ''); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_mktNm_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '2'); } }, { id: "if_mktNm_2_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '3'); } }, { id: "if_mktNm_3_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '4'); } }, { id: "if_mktNm_4_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '5'); } }, { id: "if_mktNm_5_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '55'); } }, { id: "if_mktNm_6_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '6'); } }, { id: "if_mktNm_7_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '7'); } }, { id: "if_mktNm_8_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '8'); } }, { id: "if_mktNm_9_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '9'); } }, { id: "if_mktNm_10_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '10'); } }, { id: "if_mktNm_11_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '11'); } }, { id: "if_mktNm_12_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '12'); } }, { id: "if_mktNm_13_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '13'); } }, { id: "if_mktNm_14_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '14'); } }, { id: "if_mktNm_15_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '15'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.setComma();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf35101.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf35101.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_self_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_self_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_self_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf35101.btn_self_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setComma = function () {
    /* sdd-asis-lifecycle:begin setComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.num.formatNumber($('#ipt_expPayAmt')[0]);
    $c.num.formatNumber($('#ipt_dcSales')[0]);
    $('#exp_pay_amt_td').text($c.util.getComponent('ipt_expPayAmt').getValue());
    $('#dc_sales_td').text($c.util.getComponent('ipt_dcSales').getValue());
    /* sdd-asis-lifecycle:end */
};
